sc_cat_item_producer.script:
(function () {

    // 1. Read producer variables
    var hospital = ('' + producer.hospital_name).trim();
    var city = producer.city;
    var address = producer.address;
    var phone = producer.phone;
    var email = producer.email;
    var admin = producer.admin;
    var hold_hours = producer.hold_hours_planned;
    var emergency_hours = producer.hold_hours_emergency;
    var blocks = parseInt(producer.block_count, 10) || 0;
    var floors = parseInt(producer.floor_count_per_block, 10) || 0;

    if (!hospital || hospital === 'undefined') {
        gs.error('Hospital producer: hospital_name variable is empty.');
        current.setAbortAction(true);
        return;
    }

    // 2. Create the Top-Level Location in cmn_location
    var grLoc = new GlideRecord('cmn_location');
    grLoc.initialize();
    grLoc.name = hospital;
    grLoc.city = city;
    grLoc.phone = phone;
    var loc_id = grLoc.insert();

    if (!loc_id) {
        gs.error('Hospital producer: root location insert failed: ' + grLoc.getLastErrorMessage());
        current.setAbortAction(true);
        return;
    }

    // 3. Create Blocks and Floors under the root location (loc_id)
    for (var i = 1; i <= blocks; i++) {
        var grBlock = new GlideRecord('cmn_location');
        grBlock.initialize();
        grBlock.name = 'Block ' + i;
        grBlock.city = city;
        grBlock.phone = phone;
        grBlock.parent = loc_id;
        var block_id = grBlock.insert();

        if (!block_id) {
            gs.error('Hospital producer: Block ' + i + ' insert failed: ' + grBlock.getLastErrorMessage());
            continue;
        }

        for (var j = 1; j <= floors; j++) {
            var grFloor = new GlideRecord('cmn_location');
            grFloor.initialize();
            grFloor.name = 'Block ' + i + ' Floor ' + j;
            grFloor.city = city;
            grFloor.phone = phone;
            grFloor.parent = block_id;
            grFloor.insert();
        }
    }

    // 4. Populate 'current' (ServiceNow automatically inserts this SINGLE record)
    current.name = hospital;
    current.city = city;
    current.address = address;
    current.phone = phone;
    current.email = email;
    current.hospital_administrator = admin;
    current.hold_hours_planned = hold_hours;
    current.hold_hours_emergency = emergency_hours;
    current.parent = loc_id; // <--- Populates 'Root Location'

})();
